mapper.select:
SELECT * FROM customer_balance_movement
WHERE source_type = #{sourceType}
  AND source_id = #{sourceId}
  AND deleted = FALSE

SELECT m.id                     AS id,
       m.movement_no            AS movementNo,
       m.account_id             AS accountId,
       m.settlement_customer_id AS settlementCustomerId,
       sc.name                  AS settlementCustomerName,
       m.customer_id            AS customerId,
       bc.name                  AS customerName,
       m.type                   AS movementType,
       m.direction              AS direction,
       m.amount                 AS amount,
       m.source_type            AS sourceType,
       m.source_id              AS sourceId,
       m.reason                 AS reason,
       m.occurred_at            AS occurredAt,
       m.created_at             AS createdAt,
       m.created_by             AS operator
FROM customer_balance_movement m
         JOIN customer sc ON sc.id = m.settlement_customer_id AND sc.deleted = FALSE
         LEFT JOIN customer bc ON bc.id = m.customer_id AND bc.deleted = FALSE
WHERE m.deleted = FALSE

    AND FALSE


        AND sc.seller_id IN
        #{sellerId}


AND m.id = #{query.movementId}
AND m.source_type = #{query.sourceType}
AND m.source_id = #{query.sourceId}

    AND m.settlement_customer_id = #{query.settlementCustomerId}

AND m.customer_id = #{query.customerId}
AND m.type = #{query.type}
AND m.direction = #{query.direction}
AND m.occurred_at >= #{query.occurredFrom}
AND m.occurred_at < #{query.occurredTo}
ORDER BY m.occurred_at DESC, m.id DESC
